<script setup lang="ts">
import { unwrap } from '~/api/client'; import { displayError } from '~/utils/errors'; import { formatDate, statusLabel } from '~/utils/format';
definePageMeta({ middleware: 'auth' }); const api = useMarketplaceApi(); const route = useRoute(); const cartApi = useCart(); const copied = ref(false);
const { data, error, status, refresh } = await useAsyncData(`shipment-${route.params.id}`, async () => { if (!cartApi.account.value) await cartApi.load(); return unwrap(await api.GET('/buyer-accounts/{buyerAccountId}/shipments/{shipmentId}', { params: { path: { buyerAccountId: cartApi.account.value!.id, shipmentId: String(route.params.id) } }, cache: 'no-store' })); }, { server: false });
async function copyWaybill() { if (!data.value?.waybill_id) return; await navigator.clipboard.writeText(data.value.waybill_id); copied.value = true; setTimeout(() => { copied.value = false; }, 1600); }
useSeoMeta({ title: 'Lacak pengiriman — Niaga' });
</script>
<template><main id="main-content" class="page-shell"><BuyerNav/><ApiState :pending="status === 'idle' || status === 'pending'" :error="error ? displayError(error) : null" @retry="refresh"><template v-if="data"><div class="section-heading"><div><p class="eyebrow">Tracking</p><h1>Lacak pengiriman</h1></div><span class="badge">{{ statusLabel(data.state) }}</span></div><div class="order-detail-grid"><section class="surface"><h2>Perjalanan paket</h2><ol v-if="data.tracking_events.length" class="timeline"><li v-for="event in data.tracking_events" :key="`${event.status}-${event.occurred_at}`"><span/><div><strong>{{ statusLabel(event.status) }}</strong><p>{{ event.description }}</p><small>{{ formatDate(event.occurred_at) }}</small></div></li></ol><ApiState v-else empty empty-title="Belum ada pembaruan" empty-message="Status akan muncul setelah kurir memproses paket."/></section><aside class="surface order-summary"><h2>Informasi kurir</h2><p><strong>{{ data.courier_code?.toUpperCase() || 'Belum dipilih' }}</strong><br>{{ data.service_code || '' }}</p><template v-if="data.waybill_id"><code>{{ data.waybill_id }}</code><button class="button--secondary" @click="copyWaybill">{{ copied ? 'Tersalin' : 'Salin nomor resi' }}</button></template><p class="muted">Perubahan resi dan biaya aktual tidak menambah tagihan pembeli secara otomatis.</p></aside></div></template></ApiState></main></template>
